function minOperations(nums) {
  const n = nums.length;
  const gcd = (a, b) => {
    while (b !== 0) {
      const rest = a % b;
      a = b;
      b = rest;
    }
    return a;
  };
  let ones = 0;
  for (const value of nums) {
    if (value === 1) {
      ones++;
    }
  }
  if (ones > 0) {
    return n - ones;
  }
  let shortest = Infinity;
  for (let left = 0; left < n; left++) {
    let current = nums[left];
    for (let right = left + 1; right < n; right++) {
      current = gcd(current, nums[right]);
      if (current === 1) {
        shortest = Math.min(shortest, right - left);
        break;
      }
    }
  }
  if (shortest === Infinity) {
    return -1;
  }
  return shortest + n - 1;
}

