function minOperations(nums) {
  // Try stretches from shortest to longest, recomputing each stretch's gcd from scratch.
  const gcdOf = list => list.reduce((a, b) => {
    while (b) [a, b] = [b, a % b];
    return a;
  });
  const n = nums.length;
  const ones = nums.filter(v => v === 1).length;
  if (ones) return n - ones;
  for (let len = 2; len <= n; len++) {
    for (let start = 0; start + len <= n; start++) {
      if (gcdOf(nums.slice(start, start + len)) === 1) return (len - 1) + (n - 1);
    }
  }
  return -1;
}

