function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 30 + pick(21) : 2 + pick(4);
  const mode = rand();
  const nums = [];
  // 510510 = 2*3*5*7*11*13*17; dropping one or two primes from it makes values that share many factors.
  const primes = [2, 3, 5, 7, 11, 13, 17];
  for (let i = 0; i < n; i++) {
    if (size === 'small') {
      if (mode < 0.15) nums.push(2 * (1 + pick(8)));
      else if (mode < 0.45) nums.push(rand() < 0.3 ? 1 : 1 + pick(12));
      else if (mode < 0.7) nums.push([6, 10, 15, 30, 12, 20, 45][pick(7)]);
      else nums.push(1 + pick(30));
    } else {
      if (mode < 0.2) nums.push(2 * (1 + pick(500000)));
      else if (mode < 0.35) nums.push(rand() < 0.1 ? 1 : 1 + pick(1000000));
      else if (mode < 0.55) nums.push(1 + pick(1000000));
      else {
        let value = 510510 / primes[pick(7)];
        if (rand() < 0.5) {
          const other = primes[pick(7)];
          if (value % other === 0) value /= other;
        }
        nums.push(value);
      }
    }
  }
  return [nums];
}
